# ── Enums ─────────────────────────────────────────────────────────────────────

class Status(enum.Enum):
    PENDING   = "pending"
    RUNNING   = "running"
    SUCCESS   = "success"
    FAILED    = "failed"
    CANCELLED = "cancelled"

    def is_terminal(self) -> bool:
        return self in {Status.SUCCESS, Status.FAILED, Status.CANCELLED}


class Priority(enum.IntEnum):
    LOW    = 1
    NORMAL = 5
    HIGH   = 10
    URGENT = 20


class Flag(enum.Flag):
    READ    = enum.auto()
    WRITE   = enum.auto()
    EXECUTE = enum.auto()
    RWX     = READ | WRITE | EXECUTE


# ── Protocols ─────────────────────────────────────────────────────────────────

@runtime_checkable
class Serialisable(Protocol):
    def to_dict(self) -> dict: ...

    @classmethod
    def from_dict(cls, data: dict) -> "Serialisable": ...


@runtime_checkable
class Runnable(Protocol):
    async def run(self) -> str: ...


# ── Dataclasses ───────────────────────────────────────────────────────────────

@dataclasses.dataclass(order=True, frozen=False, slots=True)
class Point:
    x: float
    y: float

    def distance(self, other: Point) -> float:
        return ((self.x - other.x) ** 2 + (self.y - other.y) ** 2) ** 0.5


@dataclasses.dataclass
class Task:
    func: Callable[[], Awaitable[str]]
    name: str

    status: Status = Status.PENDING
    priority: Priority = Priority.NORMAL

    def start(self) -> None:
        if self.status.is_terminal():
            raise RuntimeError(f"{self.name} already completed!")

        self.status = Status.RUNNING
        try:
            result = asyncio.run(self.func())
        except BaseException as exc:
            self.status = Status.FAILED
            raise exc
        else:
            self.status = Status.SUCCESS
        finally:
            print(f"[{time.strftime('%H:%M:%S')}] Finished {self.name}")

def map_async(func: Callable[[str], Awaitable[str]], tasks: list[Task]) -> list[Awaitable[str]]:
    results = []
    for task in tasks:
        loop = asyncio.get_running_loop()
        future = asyncio.ensure_future(task.start(), loop=loop)
        results.append(asyncio.wrap_future(future))
    return asyncio.gather(*results)


